options.getOption:
// How many satellites are at least 25° above the chosen point, every two
// minutes over the last orbit, stacked by shell. The band is
// the window the timeline holds (${starFrom} to ${starTo}). The other filters
// apply; the window does not, so the whole orbit stays in view.

// @constants begin
const COLORS = { '43°': '#FF9830', '53°': '#5794F2', '70°': '#73BF69', 'Polar 97.6°': '#B877D9' };
const SHELLS = ['53°', '43°', '70°', 'Polar 97.6°'];
// @constants end

const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const lines = theme.colors.border.weak;
const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);

const time = col('time').map(Number);
const shell = col('shell');
const n = col('n').map(Number);
const times = [...new Set(time)].sort((a, b) => a - b);
const at = new Map(times.map((t, i) => [t, i]));
const bySh = Object.fromEntries(SHELLS.map((s) => [s, times.map(() => 0)]));
for (let i = 0; i < time.length; i++) {
  if (bySh[shell[i]]) {
    bySh[shell[i]][at.get(time[i])] = n[i];
  }
}

const from = Date.parse(context.grafana.replaceVariables('${starFrom}'));
const to = Date.parse(context.grafana.replaceVariables('${starTo}'));
const band = Number.isFinite(from) && Number.isFinite(to)
  ? { silent: true, itemStyle: { color: 'rgba(128,128,128,0.18)' }, data: [[{ xAxis: from }, { xAxis: to }]] }
  : undefined;

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 16, top: 28, bottom: 8, containLabel: true },
  legend: { top: 0, right: 8, textStyle: { color: muted }, itemWidth: 10, itemHeight: 10 },
  tooltip: {
    trigger: 'axis',
    formatter: (items) => {
      const total = items.reduce((s, it) => s + (it.value[1] || 0), 0);
      const when = new Date(items[0].value[0]).toISOString().slice(11, 16);
      return `<b>${when} UTC</b> · ${total} above 25°<br/>` +
        items.filter((it) => it.value[1]).map((it) => `${it.marker}${it.seriesName}: ${it.value[1]}`).join('<br/>');
    },
  },
  xAxis: {
    type: 'time', axisLabel: { color: muted, formatter: (v) => new Date(v).toISOString().slice(11, 16) },
    axisLine: { lineStyle: { color: lines } }, splitLine: { show: false },
  },
  yAxis: {
    type: 'value', name: 'Satellites above 25°', nameTextStyle: { color: muted, align: 'left' },
    axisLabel: { color: muted }, splitLine: { lineStyle: { color: lines } },
  },
  series: SHELLS.map((s, k) => ({
    name: s, type: 'line', stack: 'all', symbol: 'none', step: 'middle',
    lineStyle: { width: 0 }, areaStyle: { color: COLORS[s], opacity: 0.85 },
    itemStyle: { color: COLORS[s] },
    data: times.map((t, i) => [t, bySh[s][i]]),
    markArea: k === 0 ? band : undefined,
  })),
};

// The sky over the chosen point, as a receiver sees it: zenith in the middle,
// the horizon at the edge (10° of elevation), north up and east to the right.
// Each line is a satellite's pass across the window the timeline holds (the
// last ten minutes when it holds none), its dot where the satellite is at the
// window's end. Inside the dashed ring, 25° above the
// horizon, a Starlink dish can use it. Hover a dot for the satellite.
// The window is read as ${starFrom} and ${starTo}.

// @constants begin
const COLORS = { '43°': '#FF9830', '53°': '#5794F2', '70°': '#73BF69', 'Polar 97.6°': '#B877D9' };
const MIN_ELEVATION = 10; // the edge of the chart
const DISH_ELEVATION = 25; // the dashed ring
// @constants end

const theme = context.grafana.theme;
const text = theme.colors.text.primary;
const muted = theme.colors.text.secondary;
const lines = theme.colors.border.weak;
const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);

const norad = col('norad');
const name = col('name');
const shell = col('shell');
const az = col('az').map(Number);
const el = col('el').map(Number);
const last = col('last');

// One line per satellite, in the order the query sorts them (by satellite, then time).
const passes = new Map();
const now = [];
for (let i = 0; i < norad.length; i++) {
  const key = norad[i];
  if (!passes.has(key)) {
    passes.set(key, { shell: shell[i], points: [] });
  }
  passes.get(key).points.push([90 - el[i], az[i]]);
  if (last[i]) {
    now.push({ value: [90 - el[i], az[i]], name: name[i], shell: shell[i], el: el[i], az: az[i] });
  }
}

const series = [];
for (const pass of passes.values()) {
  series.push({
    type: 'line', coordinateSystem: 'polar', silent: true, symbol: 'none',
    data: pass.points,
    lineStyle: { color: COLORS[pass.shell] || muted, width: 1, opacity: 0.35 },
  });
}
series.push({
  type: 'line', coordinateSystem: 'polar', silent: true, symbol: 'none',
  data: Array.from({ length: 73 }, (_, k) => [90 - DISH_ELEVATION, k * 5]),
  lineStyle: { color: text, width: 1.5, type: 'dashed', opacity: 0.9 },
});
for (const s of Object.keys(COLORS)) {
  series.push({
    name: s, type: 'scatter', coordinateSystem: 'polar', symbolSize: 6,
    itemStyle: { color: COLORS[s], borderColor: 'rgba(0,0,0,0.5)', borderWidth: 0.5 },
    data: now.filter((d) => d.shell === s),
  });
}

const visible = now.filter((d) => d.el >= DISH_ELEVATION).length;
const compass = { 0: 'N', 90: 'E', 180: 'S', 270: 'W' };

return {
  animation: false,
  backgroundColor: 'transparent',
  title: {
    text: `${visible.toLocaleString()} above ${DISH_ELEVATION}° · ${now.length.toLocaleString()} above ${MIN_ELEVATION}°`,
    left: 'center', top: 0, textStyle: { color: text, fontSize: 12, fontWeight: 500 },
  },
  legend: { bottom: 0, textStyle: { color: muted }, itemWidth: 10, itemHeight: 10, icon: 'circle' },
  polar: { center: ['50%', '52%'], radius: '76%' },
  angleAxis: {
    type: 'value', min: 0, max: 360, interval: 45, startAngle: 90, clockwise: true,
    axisLine: { lineStyle: { color: lines } },
    axisLabel: { color: muted, formatter: (v) => compass[v] || '' },
    splitLine: { lineStyle: { color: lines } },
    axisTick: { show: false },
  },
  radiusAxis: {
    type: 'value', min: 0, max: 90 - MIN_ELEVATION, interval: 20,
    axisLine: { show: false }, axisTick: { show: false },
    axisLabel: { color: muted, fontSize: 9, formatter: (v) => `${90 - v}°` },
    splitLine: { lineStyle: { color: lines } },
  },
  tooltip: {
    trigger: 'item',
    formatter: (p) => p.data && p.data.name
      ? `<b>${p.data.name}</b><br/>${p.data.shell} shell<br/>elevation ${p.data.el.toFixed(0)}°, azimuth ${p.data.az.toFixed(0)}°`
      : '',
  },
  series,
};
